WITH valid_employees AS (SELECT * FROM employees WHERE email LIKE '%@gmail.com' AND full_name IS NOT NULL AND manager_id IN (25, 30)), employees_stats AS (SELECT job_title, DATE_FORMAT(hire_date, 'yyyy-MM') AS hire_month, COUNT(CASE WHEN level = 'L4' THEN 1 END) AS l4_count FROM valid_employees GROUP BY job_title, DATE_FORMAT(hire_date, 'yyyy-MM')) SELECT job_title, l4_count FROM employees_stats
